import {createMovementList} from './movement-list-ui.js?v=34';
import {createAmChartPanel} from './amchart-ui.js?v=34';
import {fitStatementRange,statementCoverage} from './statement-model.js?v=19';
import {withBalanceEvents} from './balance-events.js?v=19';
import {overviewData} from './overview-model.js?v=19';
import {presetRange,validDate,bucketCount,moveDate,rangeDays} from './range-model.js?v=19';
import {remaining,total} from './data.js?v=19';

export function createOverview(a){
  const {esc,money,fullDate,icon,btn}=a;
  const preferences=new Map();let currentData,fullData,error='',activeCompany=null;
  const movements=createMovementList(a,{settings,refresh});
  const chart=createAmChartPanel(a,{settings,data:()=>fullData,refresh,zoom:selectZoom,select:selectArea});
  function settings(){if(activeCompany!==a.company){error='';activeCompany=a.company;}if(!preferences.has(a.company))preferences.set(a.company,{range:a.state.dataset?.overviewRange||fitStatementRange(a.state,a.company,presetRange('month',a.month+'-18'))||a.state.dataset?.period||presetRange('month',a.month+'-18'),preset:a.state.dataset?.overviewRange?'year':'month',ids:a.scope('accounts').map(x=>x.id),projection:true,tx:'all',all:false,movementGroup:'category',includeInitial:true,expandedGroups:[],completeGroups:[],chartZoomRange:null,chartSelectionRange:null,chartYRange:null,chartMode:'zoom',chartComposition:'bank',chartHidden:[],chartWheel:false,chartDay:null,chartBar:null,chartMovement:null,chartBasis:a.state.dataset?'reported':'cash'});return preferences.get(a.company);}
  function activeRange(){const s=settings();return s.chartDay?{start:s.chartDay,end:s.chartDay}:s.chartSelectionRange||s.chartZoomRange||s.range;}
  function data(range=activeRange()){return withBalanceEvents(overviewData(a.state,a.company,range,settings().ids),a.state,a.company,range);}
  function selectZoom(range){
    const s=settings();s.chartZoomRange=range.start===s.range.start&&range.end===s.range.end?null:range;s.chartSelectionRange=null;s.chartDay=null;s.chartBar=null;
    updateSelection();
  }
  function selectArea(range){const s=settings();s.chartSelectionRange=range;s.chartDay=null;s.chartBar=null;updateSelection();}
  function updateSelection(){
    const range=activeRange();
    currentData=data();
    for(const [selector,html] of [['[data-ov-summary]',summary(currentData)],['[data-ov-movement-panel]',movementPanel(currentData,settings())],['[data-ov-pending-panel]',pendingPanel(currentData)],['[data-ov-selection]',selectionLabel()]]){
      const node=document.querySelector(selector);if(node)node.innerHTML=html;
    }
    const dayInput=document.querySelector('[data-am-day]');if(dayInput)dayInput.value=range.end;
    document.querySelector('[data-ov-chart-back]')?.remove();
  }
  function selectionLabel(){const range=activeRange();return `Analisando ${fullDate(range.start)} — ${fullDate(range.end)} · totais, movimentação, obrigações e exportação neste intervalo.`;}
  function summary(d){return `<div><span>Saldo dos extratos · abertura</span><strong>${money(d.summary.opening)}</strong></div><div><span>Créditos nos extratos</span><strong class="incoming">${money(d.summary.incoming)}</strong></div><div><span>Débitos nos extratos</span><strong class="outgoing">${money(d.summary.outgoing)}</strong></div><div class="ov-closing"><span>Saldo dos extratos · fechamento</span><strong>${money(d.summary.closing)}</strong><small>Variação: ${money(d.summary.movement)}</small></div>`;}
  function movementPanel(d,s){return `<div class="panel-head"><div><h2>${s.chartDay?'Movimentação de '+fullDate(s.chartDay):'Movimentação do intervalo'}</h2><p>${d.transactions.length} lançamentos · abra para ver composição e documentos</p></div></div>${movements.render(d,s)}`;}
  function pendingPanel(d){const pending=d.obligations.filter(o=>remaining(a.state,o)>0);return `<div class="panel-head"><div><h2>Obrigações do intervalo</h2><p>Em aberto, pela data de vencimento</p></div></div><div class="ov-pending-totals"><div><small>A receber</small><strong>${money(d.summary.pendingIn)}</strong></div><div><small>A pagar</small><strong>${money(d.summary.pendingOut)}</strong></div></div><div class="ov-records">${pending.map(o=>`<button class="ov-record" data-open="obligation" data-id="${esc(o.id)}"><span><b>${esc(o.title)}</b><small>${fullDate(o.due)} · ${esc(o.party)} · ${o.kind==='in'?'A receber':'A pagar'}</small></span><strong>${money(remaining(a.state,o))}</strong>${icon('chevron')}</button>`).join('')||'<p class="ov-empty">Nenhuma obrigação em aberto neste intervalo.</p>'}</div><div class="next-action">Saldo com essas pendências: <strong>${money(d.projected)}</strong>.</div>`;}
  function controls(){const s=settings();return `<div class="ov-period"><div class="ov-presets"><span>Selecione o período</span><div class="segments">${[['current',a.state.dataset?'Último extrato':'Atual'],['day','Dia'],['week','Semana'],['month','Mês'],['year','Ano'],['custom','Personalizado']].map(([key,label])=>`<button data-ov-preset="${key}" aria-pressed="${s.preset===key}" class="${s.preset===key?'active':''}">${label}</button>`).join('')}</div></div><div class="ov-range"><button class="ov-arrow" data-ov-shift="-1" aria-label="Intervalo anterior">${icon('back')}</button><label>De<input type="date" data-ov-start value="${s.draft?.start??s.range.start}" aria-label="Início do período da visão geral"></label><label>Até<input type="date" data-ov-end value="${s.draft?.end??s.range.end}" aria-label="Fim do período da visão geral"></label>${btn('Aplicar','data-ov-apply="1"')}<button class="ov-arrow" data-ov-shift="1" aria-label="Intervalo seguinte">${icon('chevron')}</button></div><p class="ov-error" role="alert">${esc(error)}</p><p class="ov-period-note">${fullDate(s.range.start)} a ${fullDate(s.range.end)} · período carregado. Use o slider abaixo para selecionar um trecho do histórico. Referência dos dados: ${fullDate(statementCoverage(a.state,a.company,settings().ids)?.end||a.NOW)}.</p>${a.state.dataset?.missing?.length?'<p class="statement-coverage">Bradesco: 01/01–18/11 · BB: 01/01–31/10. Falta novembro do BB. Para ver novembro, marque só Bradesco e escolha Último extrato.</p>':''}</div>`;}
  function render(){
    const s=settings();s.range=fitStatementRange(a.state,a.company,s.range,s.ids)||statementCoverage(a.state,a.company,s.ids)||s.range;
    fullData=data(s.range);const d=currentData=data();
    return a.titleBlock('Sua operação, em perspectiva.','Histórico importado, compromissos e documentos no mesmo período.',btn('Ver na planilha','data-ov-sheet="1"','','flow'),'Visão geral')+`<section class="ov-finance">${controls()}<div class="ov-chart-panel"><div class="ov-chart-heading"><div><span class="eyebrow">${esc(a.get('companies',a.company).name)}</span><h2>Evolução do caixa</h2><p>Entradas e saídas em barras; saldo diário em linha e área. Explore o histórico pelo slider.</p></div><button class="textbtn" data-ov-export="1">${icon('download')} Exportar movimentos</button></div>${chart.render(fullData,s)}</div><p class="am-selection" data-ov-selection>${selectionLabel()}</p><div class="ov-summary" data-ov-summary>${summary(d)}</div><div class="ov-panels"><section class="panel" data-ov-movement-panel>${movementPanel(d,s)}</section><section class="panel" data-ov-pending-panel>${pendingPanel(d)}</section></div><p class="ov-scope-note">Créditos e débitos seguem a base de cada extrato e incluem transferências; não equivalem a receitas e despesas contábeis. O gráfico Conta + aplicações separa os movimentos automáticos das barras de entradas e saídas. O Bradesco já incorpora a aplicação automática no saldo; no BB, falta o saldo investido. Valor patrimonial, receitas, rateios, amortizações e resultado contábil têm apurações próprias.</p></section>`;
  }
  function refresh(focus){const top=window.scrollY,groupScroll=document.querySelector('[data-ov-groups]')?.scrollTop||0;a.render();const groups=document.querySelector('[data-ov-groups]');if(groups)groups.scrollTop=groupScroll;window.scrollTo({top,behavior:'instant'});if(focus)document.querySelector(focus)?.focus({preventScroll:true});}
  function apply(range,preset='custom'){if(!validDate(range.start)||!validDate(range.end)||range.start>range.end){error='Informe um intervalo válido, com a data final igual ou posterior à inicial.';return false;}const requested={...range},fitted=fitStatementRange(a.state,a.company,range,settings().ids);if(!fitted){error='Sem extrato para esse intervalo. Consulte a cobertura das contas em Sobre a importação.';return false;}range=fitted;if(range.start!==requested.start||range.end!==requested.end)a.toast('Exibindo apenas as datas cobertas pelos extratos importados.');if(bucketCount(range,'yearly')>366){error='Escolha um intervalo menor para visualizar o gráfico.';return false;}Object.assign(settings(),{range:{...range},preset,draft:null,chartZoomRange:null,chartSelectionRange:null,chartYRange:null,chartDay:null,chartBar:null,chartMovement:null});error='';return true;}
  function click(d){
    if(chart.click(d)||movements.click(d))return true;
    if(d.ovTransaction){const i=currentData?.points.findIndex(p=>p.transaction?.id===d.ovTransaction);if(i>=0){const t=currentData.points[i].transaction,o=a.get('obligations',t.obligation);a.open(t.imported?'transaction':o?.company===a.company?'obligation':'day',t.imported?t.id:o?.company===a.company?o.id:t.date);}return true;}
    if(d.ovAll){settings().ids=a.scope('accounts').map(x=>x.id);settings().chartZoomRange=null;settings().chartSelectionRange=null;settings().chartYRange=null;settings().chartDay=null;refresh('[data-ov-all]');return true;}
    if(d.ovPreset){const s=settings();if(d.ovPreset==='custom'){s.preset='custom';s.draft={...s.range};refresh('[data-ov-start]');return true;}const range=d.ovPreset==='current'?{start:(statementCoverage(a.state,a.company,settings().ids)?.end||a.NOW).slice(0,7)+'-01',end:statementCoverage(a.state,a.company,settings().ids)?.end||a.NOW}:presetRange(d.ovPreset,statementCoverage(a.state,a.company,settings().ids)?.end||a.NOW);apply(range,d.ovPreset);refresh(`[data-ov-preset="${d.ovPreset}"]`);return true;}
    if(d.ovApply){apply(settings().draft||settings().range);refresh('[data-ov-apply]');return true;}
    if(d.ovShift){const s=settings(),direction=Number(d.ovShift),months={month:1,year:12}[s.preset];const range=months?presetRange(s.preset,moveDate(s.range.start,0,direction*months)):{start:moveDate(s.range.start,direction*rangeDays(s.range)),end:moveDate(s.range.end,direction*rangeDays(s.range))};apply(range,months?s.preset:'custom');refresh(`[data-ov-shift="${d.ovShift}"]`);return true;}
    if(d.ovTx){settings().tx=d.ovTx;refresh(`[data-ov-tx="${d.ovTx}"]`);return true;}
    if(d.ovMore){settings().all=!settings().all;refresh('[data-ov-more]');return true;}
    if(d.ovSheet){const s=settings(),ids=a.scope('accounts').filter(x=>s.ids.includes(x.id));if(!ids.length){a.toast('Selecione uma conta para abrir a planilha.');return true;}if(ids.length>1&&ids.length!==a.scope('accounts').length){a.toast('Para abrir na planilha, escolha uma conta ou todas as contas.');return true;}a.openCashbook(activeRange(),ids.length===1?ids[0].id:'all');return true;}
    if(d.ovExport){const d=data(),safe=v=>'"'+String(v).replaceAll('"','""')+'"',rows=[[a.state.dataset?'EXTRATOS IMPORTADOS · HISTÓRICO 2026':'DEMONSTRAÇÃO · DADOS FICTÍCIOS'],['Período',fullDate(activeRange().start),fullDate(activeRange().end)],['Base','Base de saldo conforme cada extrato; consulte a cobertura e o tipo de saldo por banco'],['Data','Momento',...d.accounts.map(x=>x.name),'Saldo total','Com pendências','Lançamento','Valor do lançamento'],...d.points.map(p=>[fullDate(p.date),p.opening?'Abertura':p.transaction?'Lançamento':'Fechamento',...p.balances.map(v=>(v/100).toFixed(2).replace('.',',')),(p.total/100).toFixed(2).replace('.',','),(p.projected/100).toFixed(2).replace('.',','),p.transaction?.description||'',p.transaction?(p.transaction.amount/100).toFixed(2).replace('.',','):''])];a.download('Evolucao-caixa-'+activeRange().start+'-'+activeRange().end+'.csv','\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');return true;}
    return false;
  }
  function change(e){if(chart.change(e)||movements.change(e))return true;const el=e.target,s=settings();if(el.hasAttribute('data-ov-account')){const id=el.dataset.ovAccount;s.ids=el.checked?[...new Set([...s.ids,id])]:s.ids.filter(x=>x!==id);const fitted=fitStatementRange(a.state,a.company,s.range,s.ids);if(fitted)s.range=fitted;else s.range=statementCoverage(a.state,a.company,s.ids)||s.range;s.chartDay=null;s.chartBar=null;s.chartZoomRange=null;s.chartSelectionRange=null;s.chartYRange=null;s.chartMovement=null;refresh(`[data-ov-account="${CSS.escape(id)}"]`);return true;}if(el.hasAttribute('data-ov-projection')){s.projection=el.checked;refresh('[data-ov-projection]');return true;}if(el.hasAttribute('data-ov-start')||el.hasAttribute('data-ov-end')){s.draft??={...s.range};s.draft[el.hasAttribute('data-ov-start')?'start':'end']=el.value;return true;}return false;}
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-ov-start],[data-ov-end]')){e.preventDefault();change({target:e.target});click({ovApply:'1'});}});
  return {render,click,change,mount:chart.mount,dispose:chart.dispose,selectZoom,selectArea};
}
